// HTTP-level error codes, next to the validation codes.
const (
	codeUnauthorized = "unauthorized"
	codeBodyTooLarge = "body_too_large"
	codeInternal     = "internal"
)

const (
	maxBody      = 64 << 10
	queryTimeout = 3 * time.Second
)

// Server holds the API's dependencies.
type Server struct {
	Config  Config
	Pool    *pgxpool.Pool
	Schemas *schema.Set
	Log     *slog.Logger
	Now     func() time.Time // defaults to time.Now; tests pin it
}

// Handler builds the routes. It refuses to build an open API: with no token,
// ALLOW_UNAUTHENTICATED must have been set explicitly.
func (s *Server) Handler() (http.Handler, error) {
	if s.Config.AdminToken == "" && !s.Config.AllowUnauthenticated {
		return nil, ErrNoToken
	}
	if s.Now == nil {
		s.Now = time.Now
	}
	if s.Log == nil {
		s.Log = slog.New(slog.DiscardHandler)
	}
	api := http.NewServeMux()
	api.HandleFunc("POST /api/audience/count", s.count)
	s.campaignRoutes(api)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", s.healthz)
	mux.HandleFunc("GET /readyz", s.readyz)
	// Everything under /api is behind auth, unknown paths included, so an
	// unauthenticated caller cannot map the routes.
	mux.Handle("/api/", s.auth(api))
	return s.requestID(s.logRequests(mux)), nil
}

type ctxKey struct{}

var requestIDPattern = regexp.MustCompile(`^[A-Za-z0-9-]{1,64}$`)

// requestID keeps a well-formed X-Request-ID and replaces anything else, so
// a caller cannot inject log lines or huge values.
func (s *Server) requestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-ID")
		if !requestIDPattern.MatchString(id) {
			b := make([]byte, 8)
			_, _ = rand.Read(b)
			id = hex.EncodeToString(b)
		}
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, id)))
	})
}

func requestIDFrom(ctx context.Context) string {
	id, _ := ctx.Value(ctxKey{}).(string)
	return id
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

// logRequests logs method, path, status and duration. Never bodies, query
// strings or headers.
func (s *Server) logRequests(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		s.Log.Info("request", "method", r.Method, "path", r.URL.Path, "status", sw.status,
			"duration_ms", time.Since(start).Milliseconds(), "request_id", requestIDFrom(r.Context()))
	})
}

// auth checks the bearer token. Both sides are hashed first, so the
// constant-time compare also hides the token's length.
func (s *Server) auth(next http.Handler) http.Handler {
	if s.Config.AdminToken == "" {
		return next // only reachable with AllowUnauthenticated; Handler checks
	}
	want := sha256.Sum256([]byte(s.Config.AdminToken))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		got := sha256.Sum256([]byte(token))
		if !ok || subtle.ConstantTimeCompare(got[:], want[:]) != 1 {
			w.Header().Set("WWW-Authenticate", `Bearer realm="api"`)
			writeError(w, http.StatusUnauthorized, codeUnauthorized, "missing or invalid bearer token")
			return
		}
		next.ServeHTTP(w, r)
	})
}

func (s *Server) healthz(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// readyz checks the database is reachable and fully migrated. Liveness
// (healthz) deliberately checks nothing outside the process.
func (s *Server) readyz(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
	defer cancel()
	notReady := func(reason string) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unavailable", "reason": reason})
	}
	if err := s.Pool.Ping(ctx); err != nil {
		notReady("database unreachable")
		return
	}
	db := stdlib.OpenDBFromPool(s.Pool) // goose needs database/sql; closing it leaves the pool open
	defer db.Close()
	if pending, err := store.Pending(ctx, db); err != nil || pending {
		notReady("migrations pending")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

type countResponse struct {
	segment.Counts
	AsOf     time.Time  `json:"as_of"`
	SeededAt *time.Time `json:"seeded_at"`
}

// count validates a segment rule and returns its audience size.
func (s *Server) count(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	doc, err := schema.Decode(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, codeBodyTooLarge, "body is larger than 64 KiB")
			return
		}
		writeError(w, http.StatusBadRequest, validation.InvalidJSON, err.Error())
		return
	}

	var res validation.Result
	body, isObject := doc.(map[string]any)
	switch {
	case !isObject:
		res.Error("", validation.InvalidType, `expected an object: {"rule": {...}}`)
	default:
		for k := range body {
			if k != "rule" {
				res.Error("/"+k, validation.UnknownProperty, `only "rule" is allowed`)
			}
		}
		if _, ok := body["rule"]; !ok {
			res.Error("/rule", validation.Required, `missing required key "rule"`)
		}
	}
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	rule, res := segment.Validate(s.Schemas, body["rule"])
	if !res.OK() {
		for i := range res.Errors {
			res.Errors[i].Path = "/rule" + res.Errors[i].Path
		}
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	asOf := s.Now().UTC().Truncate(time.Microsecond)
	counts, err := segment.CountAudience(ctx, s.Pool, rule, asOf)
	if err != nil {
		s.Log.Error("count failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	seededAt, err := store.SeededAt(ctx, s.Pool)
	if err != nil {
		s.Log.Error("reading seed_meta failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "counting the audience failed")
		return
	}
	writeJSON(w, http.StatusOK, countResponse{Counts: counts, AsOf: asOf, SeededAt: seededAt})
}

type errorBody struct {
	Errors []validation.Issue `json:"errors"`
}

func issues(list []validation.Issue) errorBody { return errorBody{Errors: list} }

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, issues([]validation.Issue{{Path: "", Code: code, Message: message}}))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"net/http"
	"regexp"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/campaign"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// HTTP-level error codes of the campaign routes.
const (
	codeNotFound          = "not_found"
	codeVersionConflict   = "version_conflict"
	codeInvalidTransition = "invalid_transition"
)

// actor is who the audit trail names. There is one admin token, so there is
// one actor.
const actor = "admin"

var uuidPattern = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)

// campaignRoutes registers the stage 0 campaign routes. Generate, approve
// and the read APIs of later stages go in their own files.
func (s *Server) campaignRoutes(api *http.ServeMux) {
	api.HandleFunc("POST /api/campaigns", s.createCampaign)
	api.HandleFunc("GET /api/campaigns/{id}", s.withCampaignID(s.getCampaign))
	api.HandleFunc("POST /api/campaigns/{id}/revisions", s.withCampaignID(s.editCampaign))
	api.HandleFunc("POST /api/campaigns/{id}/reject", s.withCampaignID(s.versionAction(campaign.Reject)))
	api.HandleFunc("POST /api/campaigns/{id}/cancel", s.withCampaignID(s.versionAction(campaign.Cancel)))
}

// withCampaignID answers 404 for an id that is not a UUID, so it never
// reaches a query.
func (s *Server) withCampaignID(h func(http.ResponseWriter, *http.Request, string)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")
		if !uuidPattern.MatchString(id) {
			writeError(w, http.StatusNotFound, codeNotFound, "campaign not found")
			return
		}
		h(w, r, id)
	}
}

// decodeBody reads one JSON value. On failure it has written the response.
func decodeBody(w http.ResponseWriter, r *http.Request) (any, bool) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	doc, err := schema.Decode(r.Body)
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, codeBodyTooLarge, "body is larger than 64 KiB")
			return nil, false
		}
		writeError(w, http.StatusBadRequest, validation.InvalidJSON, err.Error())
		return nil, false
	}
	return doc, true
}

// fields checks that doc is an object with exactly the required keys.
func fields(doc any, res *validation.Result, keys ...string) map[string]any {
	m, ok := doc.(map[string]any)
	if !ok {
		res.Error("", validation.InvalidType, "expected an object")
		return nil
	}
	allowed := map[string]bool{}
	for _, k := range keys {
		allowed[k] = true
		if _, ok := m[k]; !ok {
			res.Error("/"+k, validation.Required, fmt.Sprintf("missing required key %q", k))
		}
	}
	for k := range m {
		if !allowed[k] {
			res.Error("/"+k, validation.UnknownProperty, fmt.Sprintf("key %q is not allowed", k))
		}
	}
	return m
}

// version reads the campaign version a client sends back.
func version(m map[string]any, res *validation.Result) int {
	v, present := m["version"]
	if !present {
		return 0 // reported by fields
	}
	n, ok := v.(json.Number)
	i, err := n.Int64()
	if !ok || err != nil || i < 0 || i > math.MaxInt32 {
		res.Error("/version", validation.InvalidType, "expected a non-negative integer")
		return 0
	}
	return int(i)
}

// campaignView is a campaign with its current revision and audit trail.
type campaignView struct {
	Campaign store.Campaign  `json:"campaign"`
	Revision *store.Revision `json:"revision"`
	Events   []store.Event   `json:"events"`
}

func (s *Server) loadView(ctx context.Context, id string) (campaignView, error) {
	ctx, cancel := context.WithTimeout(ctx, queryTimeout)
	defer cancel()
	var v campaignView
	var err error
	if v.Campaign, err = store.GetCampaign(ctx, s.Pool, id); err != nil {
		return v, err
	}
	if v.Campaign.CurrentRevisionID != nil {
		rev, err := store.GetRevision(ctx, s.Pool, id, *v.Campaign.CurrentRevisionID)
		if err != nil {
			return v, err
		}
		v.Revision = &rev
	}
	if v.Events, err = store.ListCampaignEvents(ctx, s.Pool, id); err != nil {
		return v, err
	}
	if v.Events == nil {
		v.Events = []store.Event{}
	}
	return v, nil
}

// writeView answers with the campaign as it is now.
func (s *Server) writeView(w http.ResponseWriter, r *http.Request, status int, id string) {
	v, err := s.loadView(r.Context(), id)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	writeJSON(w, status, v)
}

// fail maps a campaign error to its status code.
func (s *Server) fail(w http.ResponseWriter, r *http.Request, err error) {
	switch {
	case errors.Is(err, campaign.ErrNotFound):
		writeError(w, http.StatusNotFound, codeNotFound, "campaign not found")
	case errors.Is(err, campaign.ErrConflict):
		writeError(w, http.StatusConflict, codeVersionConflict, "the campaign changed; reload it and try again")
	case errors.Is(err, campaign.ErrInvalidTransition):
		writeError(w, http.StatusConflict, codeInvalidTransition, "the campaign's state does not allow this action")
	default:
		s.Log.Error("campaign request failed", "error", err, "request_id", requestIDFrom(r.Context()))
		writeError(w, http.StatusInternalServerError, codeInternal, "the request failed")
	}
}

func (s *Server) createCampaign(w http.ResponseWriter, r *http.Request) {
	doc, ok := decodeBody(w, r)
	if !ok {
		return
	}
	n, res := campaign.ValidateNew(doc, s.Config.CampaignURLHosts)
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	c, err := campaign.Create(ctx, s.Pool, n, actor)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.writeView(w, r, http.StatusCreated, c.ID)
}

func (s *Server) getCampaign(w http.ResponseWriter, r *http.Request, id string) {
	s.writeView(w, r, http.StatusOK, id)
}

// versionAction serves an action whose body is {"version": n}.
func (s *Server) versionAction(action func(context.Context, campaign.Beginner, string, int, string) error) func(http.ResponseWriter, *http.Request, string) {
	return func(w http.ResponseWriter, r *http.Request, id string) {
		doc, ok := decodeBody(w, r)
		if !ok {
			return
		}
		var res validation.Result
		m := fields(doc, &res, "version")
		v := version(m, &res)
		if !res.OK() {
			writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
		defer cancel()
		if err := action(ctx, s.Pool, id, v, actor); err != nil {
			s.fail(w, r, err)
			return
		}
		s.writeView(w, r, http.StatusOK, id)
	}
}

// editCampaign stores a human edit. It goes through the same validator as
// LLM output (rule 7); an invalid edit gets 422 and is never stored.
func (s *Server) editCampaign(w http.ResponseWriter, r *http.Request, id string) {
	doc, ok := decodeBody(w, r)
	if !ok {
		return
	}
	var res validation.Result
	m := fields(doc, &res, "base_revision_id", "version", "revision")
	v := version(m, &res)
	base, isString := m["base_revision_id"].(string)
	if _, present := m["base_revision_id"]; present && !isString {
		res.Error("/base_revision_id", validation.InvalidType, "expected a string")
	}
	var rev campaign.Revision
	var revRes validation.Result // its paths are relative to the revision, as stored
	if raw, present := m["revision"]; present {
		rev, revRes = campaign.ValidateRevision(s.Schemas, raw)
		for _, is := range revRes.Errors {
			res.Error("/revision"+is.Path, is.Code, is.Message)
		}
	}
	if !res.OK() {
		writeJSON(w, http.StatusUnprocessableEntity, issues(res.Errors))
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), queryTimeout)
	defer cancel()
	_, err := campaign.SaveEdit(ctx, s.Pool, campaign.Edit{
		ID:             id,
		BaseRevisionID: base,
		Version:        v,
		Revision:       rev,
		Warnings:       revRes.Warnings,
		Actor:          actor,
		AsOf:           s.Now().UTC(),
	})
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.writeView(w, r, http.StatusCreated, id)
}
// Package httpapi is the HTTP API: auth, request ids, the audience count
// endpoint, and health checks.
package httpapi

import (
	"errors"
	"strings"
)

// Config is read from the environment at startup.
type Config struct {
	// AdminToken is the bearer token every /api request must carry.
	AdminToken string
	// AllowUnauthenticated lets the API run without a token. Dev only, and
	// only when AdminToken is empty; a set token is always enforced.
	AllowUnauthenticated bool
	ListenAddr           string
	// CampaignURLHosts are the hosts a campaign_url may point at. Empty
	// means no campaign can be created.
	CampaignURLHosts []string
}

// ErrNoToken is returned when neither a token nor the dev escape hatch is set.
var ErrNoToken = errors.New("ADMIN_TOKEN is not set; set it, or set ALLOW_UNAUTHENTICATED=true for local development only")

// ConfigFromEnv reads ADMIN_TOKEN, ALLOW_UNAUTHENTICATED, LISTEN_ADDR and
// CAMPAIGN_URL_HOSTS (comma separated). It
// fails closed: no token and no explicit opt-out is an error, not an open API.
func ConfigFromEnv(getenv func(string) string) (Config, error) {
	c := Config{
		AdminToken:           getenv("ADMIN_TOKEN"),
		AllowUnauthenticated: getenv("ALLOW_UNAUTHENTICATED") == "true",
		ListenAddr:           getenv("LISTEN_ADDR"),
	}
	for _, h := range strings.Split(getenv("CAMPAIGN_URL_HOSTS"), ",") {
		if h = strings.ToLower(strings.TrimSpace(h)); h != "" {
			c.CampaignURLHosts = append(c.CampaignURLHosts, h)
		}
	}
	if c.ListenAddr == "" {
		c.ListenAddr = ":8080"
	}
	if c.AdminToken == "" && !c.AllowUnauthenticated {
		return Config{}, ErrNoToken
	}
	return c, nil
}

