func env(kv map[string]string) func(string) string { return func(k string) string { return kv[k] } }

func TestConfigFromEnv(t *testing.T) {
	c, err := mockprovider.ConfigFromEnv(env(map[string]string{
		"MOCKPROVIDER_SEED":                     "7",
		"MOCKPROVIDER_LATENCY":                  "20ms",
		"MOCKPROVIDER_RATE_500":                 "0.05",
		"MOCKPROVIDER_RATE_503":                 "0.05",
		"MOCKPROVIDER_RATE_429":                 "0.04",
		"MOCKPROVIDER_RATE_429_NO_RETRY_AFTER":  "0.01",
		"MOCKPROVIDER_RATE_400":                 "0.01",
		"MOCKPROVIDER_RATE_HANG":                "0.02",
		"MOCKPROVIDER_RATE_DROP":                "0.03",
		"MOCKPROVIDER_RATE_LATE":                "0.01",
		"MOCKPROVIDER_RETRY_AFTER":              "2s",
		"MOCKPROVIDER_CHAOS_HEADER":             "true",
	}))
	if err != nil {
		t.Fatal(err)
	}
	want := mockprovider.Config{
		Seed: 7, Latency: 20 * time.Millisecond,
		Rate500: 0.05, Rate503: 0.05, Rate429: 0.04, Rate429NoRetryAfter: 0.01, Rate400: 0.01,
		RateHang: 0.02, RateDrop: 0.03, RateLate: 0.01,
		RetryAfter: 2 * time.Second, ChaosHeader: true,
	}
	if c != want {
		t.Errorf("config %+v\nwant   %+v", c, want)
	}
}

// With nothing set the provider is well behaved, and X-Chaos is off: a
// deployed mock cannot be steered by a caller.
func TestConfigDefaults(t *testing.T) {
	c, err := mockprovider.ConfigFromEnv(env(nil))
	if err != nil {
		t.Fatal(err)
	}
	if c.ChaosHeader || c.Rate500 != 0 || c.Rate503 != 0 || c.Rate429 != 0 || c.RateHang != 0 || c.RateDrop != 0 || c.RateLate != 0 {
		t.Errorf("defaults inject chaos: %+v", c)
	}
}

// Only the exact value "true" turns X-Chaos on.
func TestChaosHeaderNeedsExactTrue(t *testing.T) {
	for _, v := range []string{"1", "yes", "TRUE", " true", ""} {
		c, err := mockprovider.ConfigFromEnv(env(map[string]string{"MOCKPROVIDER_CHAOS_HEADER": v}))
		if err != nil {
			t.Fatalf("%q: %v", v, err)
		}
		if c.ChaosHeader {
			t.Errorf("MOCKPROVIDER_CHAOS_HEADER=%q turned X-Chaos on", v)
		}
	}
}

// A typo in a rate must stop the mock, not silently run without chaos.
func TestConfigRejectsBadValues(t *testing.T) {
	cases := map[string]string{
		"MOCKPROVIDER_RATE_500":    "abc",
		"MOCKPROVIDER_RATE_503":    "-0.1",
		"MOCKPROVIDER_RATE_DROP":   "1.5",
		"MOCKPROVIDER_SEED":        "x",
		"MOCKPROVIDER_LATENCY":     "fast",
		"MOCKPROVIDER_RETRY_AFTER": "-1s",
	}
	for k, v := range cases {
		if _, err := mockprovider.ConfigFromEnv(env(map[string]string{k: v})); err == nil {
			t.Errorf("%s=%q accepted", k, v)
		}
	}
	// The rates are shares of one draw, so together they cannot exceed 1.
	over := map[string]string{"MOCKPROVIDER_RATE_500": "0.6", "MOCKPROVIDER_RATE_503": "0.6"}
	if _, err := mockprovider.ConfigFromEnv(env(over)); err == nil {
		t.Error("rates summing to 1.2 accepted")
	}
}

