		t.Errorf("provider stats %+v; want exactly 1 send", s)
	}
	if n := len(e.prov.callsFor(id)); n == 2 && s.Replays != 1 {
		t.Errorf("2 requests but %d replays", s.Replays)
	}
	var sentUpdates int
	if err := e.pool.QueryRow(context.Background(), `SELECT count(*) FROM campaign_events WHERE campaign_id = $1 AND to_state = 'completed'`,
		c.ID).Scan(&sentUpdates); err != nil {
		t.Fatal(err)
	}
	if sentUpdates != 1 {
		t.Errorf("the campaign completed %d times", sentUpdates)
	}
}

