		f.ID, f.Revision, user, channel).Scan(&id); err != nil {
		t.Fatal(err)
	}
	if set != "" {
		if _, err := p.Exec(ctx, `UPDATE messages SET `+set+` WHERE id = $1`, id, now); err != nil {
			t.Fatalf("%s: %v", set, err)
		}
	}
